  size_t total_msgs_{0};
  size_t warmup_msgs_{0};
  size_t received_{0};
  std::vector<double> samples_us_;
  rclcpp::Subscription<example::msg::BigBytes>::SharedPtr sub_;
};

}  // namespace example

