# 自包含的 AMR Dispatcher 运行镜像（ROS 2 Jazzy）
#
# 设计要点
# --------
# 1. 替代旧的 docker/Dockerfile —— 后者 `FROM robot-amr:latest` 依赖一个只存在于
#    开发机、未随仓库分发的基础镜像，导致在任何新机器上构建直接失败。
#
# 2. 基础镜像用官方 `ros:jazzy-ros-base`（Ubuntu 24.04 noble / amd64），
#    已实测可从本机拉取。
#
# 3. 只补装项目真正需要的依赖。全仓库 find_package 扫描 + 实测确认：
#    base 镜像已含 15/17 项，仅 behaviortree_cpp 与 hardware_interface 缺失。
#    清单保留全部项作为幂等兜底。Task 4 补 Eclipse Paho MQTT C/C++
#    （vda5050_gateway_node 的 MQTT 客户端；CMake 检测不到时该目标自动跳过，
#    但清单收录保证完整构建）。Task 6 补 VDA 5050 验收链路依赖：
#    python3-paho-mqtt（scripts/mock_vda5050_vehicle.py 虚拟小车）、
#    mosquitto + mosquitto-clients（e2e 脚本起独立 broker 18884 与联调工具）。
#
#    注意：base 镜像的 apt 源本来就是明文 http
#    (http://packages.ros.org + http://archive.ubuntu.com)，实测可达，
#    因此无需替换为国内镜像源。
#
# 4. 项目源码【不烘焙进镜像】：运行时由 /workspace 绑定挂载提供。
#    这样避免 rest_gateway.cpp / dispatcher_visualizer_node.cpp 依赖的
#    相对路径加载因工作目录不确定而失效，也让镜像与代码解耦。
#
# 构建（在仓库根目录）：
#   docker build -f docker/Dockerfile.jazzy -t amr-dispatcher:jazzy .

# 滚动 tag 风险：ros:jazzy-ros-base 未钉 digest，上游重建会静默改变镜像内容
# （CI 的 build-ros2-jazzy job 使用同一镜像）。有条件时用
# `docker manifest inspect ros:jazzy-ros-base` 取 digest 钉死，形如：
#   FROM ros:jazzy-ros-base@sha256:<digest>
# 当前环境无法访问 registry（manifest inspect 超时），暂保持滚动 tag 并依赖 CI 把关。
FROM ros:jazzy-ros-base

ENV DEBIAN_FRONTEND=noninteractive
SHELL ["/bin/bash", "-c"]

RUN apt-get update && apt-get install -y --no-install-recommends \
      ros-jazzy-behaviortree-cpp \
      ros-jazzy-hardware-interface \
      ros-jazzy-rclcpp-lifecycle \
      ros-jazzy-rclcpp-action \
      ros-jazzy-nav-msgs \
      ros-jazzy-visualization-msgs \
      ros-jazzy-tf2-ros \
      ros-jazzy-tf2-geometry-msgs \
      ros-jazzy-pluginlib \
      ros-jazzy-nav2-map-server \
      ros-jazzy-ament-index-cpp \
      ros-jazzy-ament-cmake-gtest \
      ros-jazzy-rosidl-default-generators \
      ros-jazzy-rosidl-default-runtime \
      libyaml-cpp-dev \
      libgtest-dev \
      libpaho-mqtt-dev \
      libpaho-mqttpp-dev \
      python3-paho-mqtt \
      mosquitto \

=== chassis packet header ===
#pragma once

#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace amr_dispatcher_core::chassis {

struct ChassisCommand {
  double linear_x_mps = 0.0;
  double linear_y_mps = 0.0;
  double angular_z_radps = 0.0;
  // 下行帧序号（uint8 回绕）。仅 mick_binary 协议使用：MCU 回显到上行
  // 0xA1 的 last_cmd_seq，主机据此算“命令送达率”。
  // 没有它，ChassisLinkHealth 的链路质量只能统计读空与 CRC 错，
  // 命令真的在串口上丢了是测不出来的（avg_latency_ms 也恒为 0）。
  uint8_t sequence = 0;
};

// 上行 0xA1 的第 12 字节（可选扩展）。缺字节 = 全部为 0 = 无故障。
enum MickOdometryFlags : uint8_t {
  kNoFault = 0,
  kFault = 1u << 0,        // MCU 侧综合故障（PID 发散、编码器异常等）
  kUartTimeout = 1u << 1,  // 连续 200ms 未收到合法下行帧
  kEstopInput = 1u << 2,   // 急停输入有效（部分底盘会把急停状态回传）
  kOverCurrent = 1u << 3,  // 驱动器过流/过温
};

inline bool HasMickFlag(const uint8_t flags, const MickOdometryFlags bit) {
  return (flags & static_cast<uint8_t>(bit)) != 0;
}

struct ChassisOdometryPacket {
  double x_m = 0.0;
  double y_m = 0.0;
  double yaw_rad = 0.0;
  double linear_x_mps = 0.0;
  double angular_z_radps = 0.0;
  std::optional<double> battery_voltage;
  // T2/T3：上行扩展字节。旧固件（payload 12 字节）解码后两者均为 0。
  uint8_t flags = 0;
  uint8_t last_cmd_seq = 0;
};

struct ChassisStatePacket {
  std::string status;
  std::optional<double> battery_voltage;
  // T2：0xA2 的 payload[0] != 0 一直映射成 status == "fault"，但上层只比对字符串。
  // 单独暴露布尔位，让“底盘报故障”能真正进安全链（心跳下沉 -> 安全门零速）。
  bool fault = false;
};

enum class ChassisPacketKind { kOdometry, kState };

struct ChassisPacket {
  ChassisPacketKind kind = ChassisPacketKind::kState;
  ChassisOdometryPacket odometry;
  ChassisStatePacket state;

