// 关键：把具体 protobuf 类型接入 ROS 2 的两处特化。
//
// 与 ROS2-Protobuf 仓库（fork rclcpp）的做法对比：
//   - 那边改的是 rclcpp 的 get_message_type_support_handle.hpp / publisher.hpp /
//     is_ros_compatible_type.hpp，每次 ROS 升级都要重做一遍。
//   - 这里只依赖 rosidl 已经留好的两个特化点，rclcpp 一行不改。
#ifndef SPIKE__TELEMETRY_TYPESUPPORT_HPP_
#define SPIKE__TELEMETRY_TYPESUPPORT_HPP_

#include <type_traits>

#include "rclcpp/rclcpp.hpp"

#include "spike/protobuf_typesupport.hpp"
#include "telemetry.pb.h"

// ---- 1) 让 rclcpp 的编译期门禁认得这个类型 -------------------------------
// rclcpp::is_ros_compatible_type<T> 的判据是
//   is_message<T> || TypeAdapter<T>::is_specialized || ...
// 生成代码正是用「为具体类型特化 is_message」来宣告「我是消息」的，
// 所以这里走的是官方同一条路，而不是绕过它。
namespace rosidl_generator_traits
{

template<>
struct is_message<amr_dispatcher::proto::FleetTelemetry> : std::true_type {};

// rosbag2 / 部分工具会读这两个；生成代码里同样会特化它们。
template<>
inline const char * name<amr_dispatcher::proto::FleetTelemetry>()
{
  return "amr_dispatcher::proto::FleetTelemetry";
}

template<>
inline const char * data_type<amr_dispatcher::proto::FleetTelemetry>()
{
  return "amr_dispatcher::proto::FleetTelemetry";
}

// 显式特化不会自动带 inline，而本头文件会被多个 TU 包含，
// 因此下面的函数模板特化必须显式标注 inline，避免 ODR 冲突。

}  // namespace rosidl_generator_traits

// ---- 2) 让 typesupport 查询返回我们自己的 handle ---------------------------
// rclcpp::get_message_type_support_handle 的第一重载（is_message 为真）会调用
// rosidl_typesupport_cpp::get_message_type_support_handle<MessageT>()。
// 为具体类型特化它，即可在不改 rclcpp 的前提下注入 typesupport。
namespace rosidl_typesupport_cpp
{

template<>
inline const rosidl_message_type_support_t *
get_message_type_support_handle<amr_dispatcher::proto::FleetTelemetry>()
{
  return &spike::GetProtobufTypeSupport<amr_dispatcher::proto::FleetTelemetry>();
}

}  // namespace rosidl_typesupport_cpp

#endif  // SPIKE__TELEMETRY_TYPESUPPORT_HPP_

// 零 fork 的 protobuf typesupport：不修改 rclcpp，只在用户侧做两件事——
//   1) 特化 rosidl_generator_traits::is_message<ProtoT>
//   2) 特化 rosidl_typesupport_cpp::get_message_type_support_handle<ProtoT>
// rclcpp::get_message_type_support_handle 的第一个重载（is_message 为真）就会
// 走到这里，而 Publisher / Subscription 的其余模板逻辑无需任何改动。
#ifndef SPIKE__PROTOBUF_TYPESUPPORT_HPP_
#define SPIKE__PROTOBUF_TYPESUPPORT_HPP_

#include <cstdint>
#include <cstring>
#include <limits>
#include <string>
#include <type_traits>

#include <google/protobuf/message.h>

#include <fastcdr/Cdr.h>

#include <rosidl_runtime_c/message_type_support_struct.h>
#include <rosidl_typesupport_fastrtps_cpp/identifier.hpp>
#include <rosidl_typesupport_fastrtps_cpp/message_type_support.h>

#include <rosidl_runtime_cpp/traits.hpp>
// Jazzy 把该声明装在 include/rosidl_runtime_cpp/ 根下，
// 所以 include 字符串是 rosidl_typesupport_cpp/...，不含 rosidl_runtime_cpp 前缀。
#include <rosidl_typesupport_cpp/message_type_support.hpp>

namespace spike
{

template<typename T>
struct IsProtobufMessage : std::is_base_of<google::protobuf::Message, T> {};

namespace detail
{

// proto package "a.b.c" -> DDS 命名空间 "a::b::c"
inline std::string ProtoNamespace(const std::string & full_name)
{
  const auto pos = full_name.find_last_of('.');
  if (pos == std::string::npos) {
    return "protobuf";
  }
  std::string ns = full_name.substr(0, pos);
  for (std::size_t i = 0; i < ns.size(); ++i) {
    if (ns[i] == '.') {
      ns.replace(i, 1, "::");
      ++i;
    }
  }
  return ns;
}

inline std::string ProtoName(const std::string & full_name)
{
  const auto pos = full_name.find_last_of('.');
  return pos == std::string::npos ? full_name : full_name.substr(pos + 1);
}

}  // namespace detail

// 把 protobuf 消息编码成 CDR 的 sequence<uint8>，与等价 .msg（uint8[] data）
// 在 wire 上完全同形：uint32 长度前缀 + 原始字节。
template<typename ProtoT>
const rosidl_message_type_support_t & GetProtobufTypeSupport()
{
  static_assert(
    IsProtobufMessage<ProtoT>::value,
    "ProtoT must derive from google::protobuf::Message");

  static const std::string full_name = ProtoT::descriptor()->full_name();
  static const std::string message_namespace = detail::ProtoNamespace(full_name);
  static const std::string message_name = detail::ProtoName(full_name);

  static message_type_support_callbacks_t callbacks{};
  callbacks.message_namespace_ = message_namespace.c_str();
  callbacks.message_name_ = message_name.c_str();

  callbacks.get_serialized_size =
    [](const void * untyped) -> uint32_t
    {
      const auto * msg = static_cast<const ProtoT *>(untyped);
      const std::size_t n = msg->ByteSizeLong();
      if (n > static_cast<std::size_t>(std::numeric_limits<uint32_t>::max()) - 4u) {
        return 0u;
      }
      return static_cast<uint32_t>(4u + n);
    };

  callbacks.cdr_serialize =
    [](const void * untyped, eprosima::fastcdr::Cdr & cdr) -> bool
    {
      const auto * msg = static_cast<const ProtoT *>(untyped);
      std::string buf;
      if (!msg->SerializeToString(&buf)) {
        return false;
      }
      const auto n = static_cast<uint32_t>(buf.size());
      cdr << n;
      if (n > 0) {
        cdr.serialize_array(reinterpret_cast<const uint8_t *>(buf.data()), n);
      }
      return true;
    };

  callbacks.cdr_deserialize =
    [](eprosima::fastcdr::Cdr & cdr, void * untyped) -> bool
    {
      auto * msg = static_cast<ProtoT *>(untyped);
      uint32_t n = 0;
      cdr >> n;
      if (n == 0) {
        msg->Clear();
        return true;
      }
      std::string buf;
      buf.resize(n);
      cdr.deserialize_array(reinterpret_cast<uint8_t *>(&buf[0]), n);
      return msg->ParseFromArray(buf.data(), static_cast<int>(n));
    };

  callbacks.max_serialized_size =
    [](char & bounds_info) -> size_t
    {
      bounds_info = ROSIDL_TYPESUPPORT_FASTRTPS_UNBOUNDED_TYPE;
      return 0u;
    };

  static rosidl_message_type_support_t ts{};
  ts.typesupport_identifier = rosidl_typesupport_fastrtps_cpp::typesupport_identifier;
  ts.data = &callbacks;
  ts.func =
    [](const rosidl_message_type_support_t * handle, const char * id)
    -> const rosidl_message_type_support_t *
    {
      if (!handle || !id) {
        return nullptr;
      }
      if (std::strcmp(id, rosidl_typesupport_fastrtps_cpp::typesupport_identifier) == 0) {
        return handle;
      }
      return nullptr;
    };

  return ts;
}

}  // namespace spike

#endif  // SPIKE__PROTOBUF_TYPESUPPORT_HPP_

// 验证：同一 protobuf 类型能否作为 create_subscription<T> 的类型参数。
#include <cstdint>
#include <memory>

#include "spike/telemetry_typesupport.hpp"

namespace
{

class ProtoListener : public rclcpp::Node
{
public:
  explicit ProtoListener(const rclcpp::NodeOptions & options)
  : rclcpp::Node("proto_listener", options)
  {
    sub_ = this->create_subscription<amr_dispatcher::proto::FleetTelemetry>(
      "spike_telemetry", rclcpp::QoS(10),
      [this](const amr_dispatcher::proto::FleetTelemetry & msg) { this->on_msg(msg); });
  }

private:
  void on_msg(const amr_dispatcher::proto::FleetTelemetry & msg)
  {
    const int64_t dt_ns = this->get_clock()->now().nanoseconds() - msg.stamp_ns();
    RCLCPP_INFO(
      this->get_logger(),
      "recv seq=%llu vehicle=%s x=%.2f payload=%zu latency=%.2fms",
      static_cast<unsigned long long>(msg.sequence()), msg.vehicle_id().c_str(),
      msg.x_m(), msg.payload().size(), static_cast<double>(dt_ns) / 1e6);
  }

  rclcpp::Subscription<amr_dispatcher::proto::FleetTelemetry>::SharedPtr sub_;
};

}  // namespace

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ProtoListener>(rclcpp::NodeOptions{}));
  rclcpp::shutdown();
  return 0;
}

// 验证：protobuf 类型能否直接作为 create_publisher<T> 的类型参数。
#include <chrono>
#include <cstdint>
#include <memory>
#include <string>

#include "spike/telemetry_typesupport.hpp"

using namespace std::chrono_literals;

namespace
{

class ProtoTalker : public rclcpp::Node
{
public:
  explicit ProtoTalker(const rclcpp::NodeOptions & options)
  : rclcpp::Node("proto_talker", options)
  {
    pub_ = this->create_publisher<amr_dispatcher::proto::FleetTelemetry>(
      "spike_telemetry", rclcpp::QoS(10));

    timer_ = this->create_wall_timer(200ms, [this]() { this->tick(); });
  }

private:
  void tick()
  {
    amr_dispatcher::proto::FleetTelemetry msg;
    msg.set_stamp_ns(this->get_clock()->now().nanoseconds());
    msg.set_vehicle_id("amr-01");
    msg.set_x_m(1.5);
    msg.set_y_m(2.5);
    msg.set_yaw_rad(0.25);
    msg.set_sequence(count_++);
    msg.set_payload(std::string(64, 'x'));

    pub_->publish(msg);
    RCLCPP_INFO(
      this->get_logger(), "published seq=%llu bytes=%zu",
      static_cast<unsigned long long>(msg.sequence()), msg.ByteSizeLong());
  }

  std::size_t count_{0};
  rclcpp::Publisher<amr_dispatcher::proto::FleetTelemetry>::SharedPtr pub_;
  rclcpp::TimerBase::SharedPtr timer_;
};

}  // namespace

int main(int argc, char ** argv)
{
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ProtoTalker>(rclcpp::NodeOptions{}));
  rclcpp::shutdown();
  return 0;
}

