      bounds_info = ROSIDL_TYPESUPPORT_FASTRTPS_UNBOUNDED_TYPE;
      return 0u;
    };

  static rosidl_message_type_support_t ts{};
  ts.typesupport_identifier = rosidl_typesupport_fastrtps_cpp::typesupport_identifier;
